			this.doc = nextDoc;
			this._fileName = nextFileName;
			this._currentFileHandle = null;
			this._requiresPasswordForSave = false;
			this._documentDigest = nextDocumentDigest;
			this._documentGeneration += 1;
			if (previousDoc) try {
				previousDoc.free();
			} catch {}
