	updateLive(rect, zoom) {
		this.ensureAttached();
		this.currentRect = rect;
		this.updatePosition(zoom);
		if (!this.isCompMode) {
			this.caretEl.style.display = "block";
			this.caretEl.style.opacity = "1";
			this.visible = true;
			if (this.blinkTimer === null) this.startBlink();
		}
	}
