/**
* [#3865] 검색 히트로 커서를 옮기고 매치를 선택 표시한다.
*
* 찾기 대화상자와 대화상자 없는 "찾기 다음"(F3) 이 **같은 이동 규칙을 써야** 한다.
* 한쪽만 셀을 다루면 같은 문서에서 Ctrl+F 는 표 안을 찾는데 F3 는 못 찾는 상태가 된다.
*
* 표 셀 매치는 `cellContext` 가 셀 안 문단을 지목한다. 이때 `paragraphIndex` 는 표가
* 놓인 바깥 문단이고, 실제 캐럿 위치는 `cellIndex` 계열 필드가 정한다.
*/
function navigateToSearchHit(ih, hit) {
	if (!ih || !hit.found) return;
	const cell = hit.cellContext;
	const startPos = cell ? {
		sectionIndex: hit.sec,
		paragraphIndex: cell.parentPara,
		charOffset: hit.charOffset,
		parentParaIndex: cell.parentPara,
		controlIndex: cell.ctrlIdx,
		cellIndex: cell.cellIdx,
		cellParaIndex: cell.cellPara
	} : {
		sectionIndex: hit.sec,
		paragraphIndex: hit.para,
		charOffset: hit.charOffset
	};
	const endPos = {
		...startPos,
		charOffset: hit.charOffset + hit.length
	};
	const cursor = ih.cursor;
	if (cell) {
		cursor?.clearSelection();
		cursor?.moveTo(startPos);
	} else ih.moveCursorTo(startPos);
	if (cursor) {
		cursor.setAnchor();
		cursor.moveTo(endPos);
	}
	ih.updateCaret?.();
}
/**
* 찾기/찾아바꾸기 모달리스 대화상자
*
* ModalDialog와 달리 편집 영역 조작이 가능하도록 overlay를 사용하지 않는다.
*/
var FindDialog = class FindDialog {
	static lastQuery = "";
	static lastCaseSensitive = false;
	_open = false;
	mode;
	services;
	wrap;
	queryInput;
	replaceInput;
	caseSensitiveCheck;
	replaceRow;
	replaceButtonRow;
	statusLabel;
	titleLabel;
	keyCaptureHandler = null;
	/** 현재 검색 결과 (바꾸기 시 위치 참조용) */
	currentHit = null;
	/** [Task #2339] history-jumped 구독 해제 핸들 (열려 있는 동안만 구독). */
	historyJumpOff = null;
	constructor(services, mode) {
		this.services = services;
		this.mode = mode;
	}
	isOpen() {
		return this._open;
	}
	show() {
		if (this._open) {
			this.focusInput();
			return;
		}
		this._open = true;
		this.build();
		document.body.appendChild(this.wrap);
		this.queryInput.value = FindDialog.lastQuery;
		this.caseSensitiveCheck.checked = FindDialog.lastCaseSensitive;
		this.applyMode();
		this.installKeyCaptureHandler();
		this.historyJumpOff = this.services.eventBus.on("history-jumped", () => {
			this.currentHit = null;
		});
		this.focusInput();
	}
	hide() {
		this._open = false;
		this.removeKeyCaptureHandler();
		this.historyJumpOff?.();
		this.historyJumpOff = null;
		this.wrap?.remove();
	}
	focusInput() {
		this.queryInput?.focus();
		this.queryInput?.select();
	}
	switchMode(mode) {
		this.mode = mode;
		this.applyMode();
	}
	findNext() {
		this.doSearch(true);
	}
	findPrev() {
		this.doSearch(false);
	}
	build() {
		this.wrap = document.createElement("div");
		this.wrap.className = "find-dialog";
		const titleBar = document.createElement("div");
		titleBar.className = "find-dialog-title";
		this.titleLabel = document.createElement("span");
		titleBar.appendChild(this.titleLabel);
		const closeBtn = document.createElement("button");
		closeBtn.className = "dialog-close";
		closeBtn.textContent = "×";
		closeBtn.addEventListener("click", () => this.hide());
		titleBar.appendChild(closeBtn);
		this.wrap.appendChild(titleBar);
		const body = document.createElement("div");
		body.className = "find-dialog-body";
		const findRow = document.createElement("div");
		findRow.className = "find-dialog-row";
		const findLabel = document.createElement("label");
		findLabel.textContent = "찾을 내용:";
		findLabel.className = "find-dialog-label";
		this.queryInput = document.createElement("input");
		this.queryInput.type = "text";
		this.queryInput.className = "find-dialog-input";
		this.queryInput.addEventListener("keydown", (e) => e.stopPropagation());
		this.queryInput.addEventListener("keyup", (e) => e.stopPropagation());
		this.queryInput.addEventListener("keypress", (e) => e.stopPropagation());
		findRow.appendChild(findLabel);
		findRow.appendChild(this.queryInput);
		body.appendChild(findRow);
		this.replaceRow = document.createElement("div");
		this.replaceRow.className = "find-dialog-row";
		const replaceLabel = document.createElement("label");
		replaceLabel.textContent = "바꿀 내용:";
		replaceLabel.className = "find-dialog-label";
		this.replaceInput = document.createElement("input");
		this.replaceInput.type = "text";
		this.replaceInput.className = "find-dialog-input";
		this.replaceInput.addEventListener("keydown", (e) => e.stopPropagation());
		this.replaceInput.addEventListener("keyup", (e) => e.stopPropagation());
		this.replaceInput.addEventListener("keypress", (e) => e.stopPropagation());
		this.replaceRow.appendChild(replaceLabel);
		this.replaceRow.appendChild(this.replaceInput);
		body.appendChild(this.replaceRow);
		const optRow = document.createElement("div");
		optRow.className = "find-dialog-row";
		this.caseSensitiveCheck = document.createElement("input");
		this.caseSensitiveCheck.type = "checkbox";
		this.caseSensitiveCheck.id = "find-case-sensitive";
		const caseLabel = document.createElement("label");
		caseLabel.htmlFor = "find-case-sensitive";
		caseLabel.textContent = " 대소문자 구분";
		optRow.appendChild(this.caseSensitiveCheck);
		optRow.appendChild(caseLabel);
		this.statusLabel = document.createElement("span");
		this.statusLabel.className = "find-dialog-status";
		optRow.appendChild(this.statusLabel);
		body.appendChild(optRow);
		this.wrap.appendChild(body);
		const btnRow = document.createElement("div");
		btnRow.className = "find-dialog-buttons";
		const prevBtn = this.createButton("이전 찾기", () => this.findPrev());
		const nextBtn = this.createButton("다음 찾기", () => this.findNext());
		btnRow.appendChild(prevBtn);
		btnRow.appendChild(nextBtn);
		this.wrap.appendChild(btnRow);
		this.replaceButtonRow = document.createElement("div");
		this.replaceButtonRow.className = "find-dialog-buttons";
		const replaceBtn = this.createButton("바꾸기", () => this.doReplace());
		const replaceAllBtn = this.createButton("모두 바꾸기", () => this.doReplaceAll());
		this.replaceButtonRow.appendChild(replaceBtn);
		this.replaceButtonRow.appendChild(replaceAllBtn);
		this.wrap.appendChild(this.replaceButtonRow);
		this.makeDraggable(titleBar);
	}
	createButton(text, handler) {
		const btn = document.createElement("button");
		btn.className = "dialog-btn";
		btn.textContent = text;
		btn.addEventListener("click", handler);
		return btn;
	}
	installKeyCaptureHandler() {
		if (this.keyCaptureHandler) return;
		this.keyCaptureHandler = (e) => {
			if (!this._open) return;
			const target = e.target;
			const isInDialog = Boolean(target && this.wrap.contains(target));
			if (e.key === "Escape") {
				e.preventDefault();
				e.stopPropagation();
				this.hide();
				return;
			}
			if (this.isFindEnter(e)) {
				e.preventDefault();
				e.stopPropagation();
				if (target === this.replaceInput && !e.shiftKey) this.doReplace();
				else this.doSearch(!e.shiftKey);
				this.focusInput();
				return;
			}
			if (isInDialog) e.stopPropagation();
		};
		document.addEventListener("keydown", this.keyCaptureHandler, true);
	}
	removeKeyCaptureHandler() {
		if (!this.keyCaptureHandler) return;
		document.removeEventListener("keydown", this.keyCaptureHandler, true);
		this.keyCaptureHandler = null;
	}
	isFindEnter(e) {
		return e.key === "Enter" && !e.altKey && !e.ctrlKey && !e.metaKey && !e.isComposing;
	}
	applyMode() {
		const isReplace = this.mode === "replace";
		this.titleLabel.textContent = isReplace ? "찾아 바꾸기" : "찾기";
		this.replaceRow.style.display = isReplace ? "" : "none";
		this.replaceButtonRow.style.display = isReplace ? "" : "none";
	}
	doSearch(forward) {
		const query = this.queryInput.value;
		if (!query) {
			this.statusLabel.textContent = "";
			return;
		}
		FindDialog.lastQuery = query;
		FindDialog.lastCaseSensitive = this.caseSensitiveCheck.checked;
		const ih = this.services.getInputHandler();
		if (!ih) return;
		const pos = ih.getCursorPosition();
		let fromSec = pos.sectionIndex;
		let fromPara = pos.paragraphIndex;
		let fromChar = pos.charOffset;
		if (!forward && this.currentHit?.found) {
			fromSec = this.currentHit.sec;
			fromPara = this.currentHit.para;
			fromChar = this.currentHit.charOffset;
		}
		const result = this.services.wasm.searchText(query, fromSec, fromPara, fromChar, forward, this.caseSensitiveCheck.checked, true);
		if (result.found) {
			this.currentHit = result;
			this.navigateToHit(result);
			if (result.wrapped) {
				this.statusLabel.style.color = "#0066cc";
				this.statusLabel.textContent = forward ? "맨 마지막입니다. 처음부터 계속합니다." : "맨 처음입니다. 끝부터 계속합니다.";
			} else this.statusLabel.textContent = "";
		} else {
			this.currentHit = null;
			this.statusLabel.style.color = "#c00";
			this.statusLabel.textContent = "검색 결과 없음";
		}
	}
	navigateToHit(hit) {
		navigateToSearchHit(this.services.getInputHandler(), hit);
	}
	doReplace() {
		if (!this.currentHit || !this.currentHit.found) {
			this.doSearch(true);
			return;
		}
		const newText = this.replaceInput.value;
		const hit = this.currentHit;
		const cell = hit.cellContext;
		const applyReplace = (wasm) => {
			if (cell) return { ok: wasm.replaceTextInCellDeferredPagination(hit.sec, cell.parentPara, cell.ctrlIdx, cell.cellIdx, cell.cellPara, hit.charOffset, hit.length, newText).ok };
			return wasm.replaceText(hit.sec, hit.para, hit.charOffset, hit.length, newText);
		};
		let result = { ok: false };
		const ih = this.services.getInputHandler();
		if (ih) ih.executeOperation({
			kind: "snapshot",
			operationType: "replaceText",
			operation: (wasm) => {
				result = applyReplace(wasm);
				return ih.getCursorPosition();
			}
		});
		else {
			result = applyReplace(this.services.wasm);
			this.services.eventBus.emit("document-changed");
		}
		if (result.ok) {
			this.currentHit = null;
			this.doSearch(true);
		}
	}
	doReplaceAll() {
		const query = this.queryInput.value;
		if (!query) return;
		const newText = this.replaceInput.value;
		let result = { ok: false };
		const ih = this.services.getInputHandler();
		if (ih) ih.executeOperation({
			kind: "snapshot",
			operationType: "replaceAll",
			operation: (wasm) => {
				result = wasm.replaceAll(query, newText, this.caseSensitiveCheck.checked);
				return ih.getCursorPosition();
			}
		});
		else {
			result = this.services.wasm.replaceAll(query, newText, this.caseSensitiveCheck.checked);
			this.services.eventBus.emit("document-changed");
		}
		if (result.ok) {
			this.statusLabel.textContent = `${result.count}개 바꿈`;
			this.currentHit = null;
		}
	}
	makeDraggable(handle) {
		let startX = 0, startY = 0, origX = 0, origY = 0;
		handle.style.cursor = "move";
		handle.addEventListener("mousedown", (e) => {
			e.preventDefault();
			startX = e.clientX;
			startY = e.clientY;
			const rect = this.wrap.getBoundingClientRect();
			origX = rect.left;
			origY = rect.top;
			const onMove = (ev) => {
				this.wrap.style.left = `${origX + ev.clientX - startX}px`;
				this.wrap.style.top = `${origY + ev.clientY - startY}px`;
				this.wrap.style.right = "auto";
			};
			const onUp = () => {
				document.removeEventListener("mousemove", onMove);
				document.removeEventListener("mouseup", onUp);
			};
			document.addEventListener("mousemove", onMove);
			document.addEventListener("mouseup", onUp);
		});
	}
};
//#endregion
//#region src/ui/goto-dialog.ts
/**
* 찾아가기 대화상자 — 쪽/책갈피 탭으로 이동 위치 선택
*/
var GotoDialog = class extends ModalDialog {
	services;
	pageInput;
	statusLabel;
	activeTab = "page";
	pagePanel;
	bookmarkPanel;
	tabBtnPage;
	tabBtnBookmark;
	bookmarkList;
	selectedBookmark = null;
	pageEnterHandler = null;
	constructor(services, tab) {
		super("찾아가기", 300);
		this.services = services;
		if (tab) this.activeTab = tab;
	}
	createBody() {
		const body = document.createElement("div");
		body.className = "goto-dialog-body";
		const tabBar = document.createElement("div");
		tabBar.className = "goto-tab-bar";
		this.tabBtnPage = document.createElement("button");
		this.tabBtnPage.className = "goto-tab-btn";
		this.tabBtnPage.textContent = "쪽";
		this.tabBtnPage.addEventListener("click", () => this.switchTab("page"));
		this.tabBtnBookmark = document.createElement("button");
		this.tabBtnBookmark.className = "goto-tab-btn";
		this.tabBtnBookmark.textContent = "책갈피";
		this.tabBtnBookmark.addEventListener("click", () => this.switchTab("bookmark"));
		tabBar.appendChild(this.tabBtnPage);
		tabBar.appendChild(this.tabBtnBookmark);
		body.appendChild(tabBar);
		this.pagePanel = document.createElement("div");
		this.pagePanel.className = "goto-panel";
		const totalPages = this.services.wasm.pageCount;
		const row = document.createElement("div");
		row.className = "dialog-row";
		const label = document.createElement("label");
		label.textContent = "쪽 번호:";
		label.style.width = "60px";
		this.pageInput = document.createElement("input");
		this.pageInput.type = "number";
		this.pageInput.min = "1";
		this.pageInput.max = String(totalPages);
		this.pageInput.value = "1";
		this.pageInput.style.width = "80px";
		this.pageInput.style.height = "24px";
		this.pageInput.style.border = "1px solid #aaa";
		this.pageInput.style.padding = "0 4px";
		this.pageInput.style.fontSize = "12px";
		const rangeLabel = document.createElement("span");
		rangeLabel.textContent = ` / ${totalPages}쪽`;
		rangeLabel.style.color = "#666";
		row.appendChild(label);
		row.appendChild(this.pageInput);
		row.appendChild(rangeLabel);
		this.pagePanel.appendChild(row);
		this.statusLabel = document.createElement("div");
		this.statusLabel.style.color = "#c00";
		this.statusLabel.style.fontSize = "11px";
		this.statusLabel.style.marginTop = "4px";
		this.pagePanel.appendChild(this.statusLabel);
		body.appendChild(this.pagePanel);
		this.bookmarkPanel = document.createElement("div");
		this.bookmarkPanel.className = "goto-panel";
		this.bookmarkList = document.createElement("div");
		this.bookmarkList.className = "goto-bookmark-list";
		this.bookmarkPanel.appendChild(this.bookmarkList);
		body.appendChild(this.bookmarkPanel);
		this.switchTab(this.activeTab);
		return body;
	}
	switchTab(tab) {
		this.activeTab = tab;
		this.tabBtnPage.classList.toggle("active", tab === "page");
		this.tabBtnBookmark.classList.toggle("active", tab === "bookmark");
		this.pagePanel.style.display = tab === "page" ? "" : "none";
		this.bookmarkPanel.style.display = tab === "bookmark" ? "" : "none";
		if (tab === "bookmark") this.refreshBookmarks();
	}
	refreshBookmarks() {
		this.bookmarkList.replaceChildren();
		this.selectedBookmark = null;
		const bookmarks = this.services.wasm.getBookmarks();
		if (bookmarks.length === 0) {
			const empty = document.createElement("div");
			empty.style.cssText = "color:#999;font-size:11px;padding:12px;text-align:center";
			empty.textContent = "등록된 책갈피가 없습니다.";
			this.bookmarkList.appendChild(empty);
			return;
		}
		bookmarks.sort((a, b) => a.name.localeCompare(b.name));
		for (const bm of bookmarks) {
			const item = document.createElement("div");
			item.className = "goto-bookmark-item";
			item.textContent = bm.name || "(이름 없음)";
			item.addEventListener("click", () => {
				this.bookmarkList.querySelectorAll(".goto-bookmark-item").forEach((el) => el.classList.remove("selected"));
				item.classList.add("selected");
				this.selectedBookmark = bm;
			});
			item.addEventListener("dblclick", () => {
				this.selectedBookmark = bm;
				this.moveToBookmark();
			});
			this.bookmarkList.appendChild(item);
		}
	}
	moveToBookmark() {
		if (!this.selectedBookmark) return;
		const bm = this.selectedBookmark;
		const ih = this.services.getInputHandler();
		if (!ih) {
			this.hide();
			return;
		}
		if (!this.tryMoveCursor(ih, bm.sec, bm.para, bm.charPos)) this.fallbackMove(ih, bm.sec, bm.para);
		this.hide();
	}
	/** moveCursorTo 래퍼 — 성공하면 true */
	tryMoveCursor(ih, sec, para, offset) {
		return ih.moveCursorTo({
			sectionIndex: sec,
			paragraphIndex: para,
			charOffset: offset
		});
	}
	/** 지정 문단 전후 ±5 범위에서 커서 이동 가능한 문단을 찾아 결과를 반환한다. */
	fallbackMove(ih, sec, para) {
		for (let d = 1; d <= 5; d++) {
			if (this.tryMoveCursor(ih, sec, para + d, 0)) return true;
			if (para - d >= 0 && this.tryMoveCursor(ih, sec, para - d, 0)) return true;
		}
		return false;
	}
	show() {
		super.show();
		this.installPageEnterHandler();
		if (this.activeTab === "page") {
			const ih = this.services.getInputHandler();
			if (ih) {
				const pos = ih.getCursorPosition();
				const pageResult = this.services.wasm.getPageOfPosition(pos.sectionIndex, pos.paragraphIndex);
				if (pageResult.ok && pageResult.page != null) this.pageInput.value = String(pageResult.page + 1);
			}
			this.pageInput.focus();
			this.pageInput.select();
		}
	}
	hide() {
		this.removePageEnterHandler();
		super.hide();
		this.services.getInputHandler()?.focus();
	}
	installPageEnterHandler() {
		if (this.pageEnterHandler) return;
		this.pageEnterHandler = (e) => {
			if (this.activeTab !== "page") return;
			if (e.target !== this.pageInput) return;
			if (e.key !== "Enter" || e.altKey || e.ctrlKey || e.metaKey || e.isComposing) return;
			e.preventDefault();
			e.stopPropagation();
			if (this.onConfirm() !== false) this.hide();
		};
		document.addEventListener("keydown", this.pageEnterHandler, true);
	}
	removePageEnterHandler() {
		if (!this.pageEnterHandler) return;
		document.removeEventListener("keydown", this.pageEnterHandler, true);
		this.pageEnterHandler = null;
	}
	onConfirm() {
		if (this.activeTab === "bookmark") {
			this.moveToBookmark();
			return;
		}
		const totalPages = this.services.wasm.pageCount;
		const pageNum = parseInt(this.pageInput.value, 10);
		if (isNaN(pageNum) || pageNum < 1 || pageNum > totalPages) {
			this.statusLabel.textContent = `1~${totalPages} 범위의 쪽 번호를 입력하세요.`;
			return false;
		}
		const globalPage = pageNum - 1;
		const posResult = this.services.wasm.getPositionOfPage(globalPage);
		if (!posResult.ok) {
			this.statusLabel.textContent = "해당 쪽을 찾을 수 없습니다.";
			return false;
		}
		if (!this.services.gotoPage(globalPage)) {
			this.statusLabel.textContent = "해당 쪽으로 화면을 이동할 수 없습니다.";
			return false;
		}
		const ih = this.services.getInputHandler();
		if (!ih) {
			this.statusLabel.textContent = "문서 입력기를 찾을 수 없습니다.";
			return false;
		}
		ih.exitFootnoteModeForBodyNavigation();
		if (!(this.tryMoveCursor(ih, posResult.sec, posResult.para, posResult.charOffset ?? 0) || this.fallbackMove(ih, posResult.sec, posResult.para))) {
			this.statusLabel.textContent = "해당 쪽의 커서 위치를 찾을 수 없습니다. 쪽 번호를 다시 입력하세요.";
			this.pageInput.focus();
			this.pageInput.select();
			return false;
		}
	}
};
//#endregion
//#region src/compare/diff-location-label.ts
/** 미리보기에 쓰이는 문자열이 “변경 내용 없음”으로 간주되는지 */
function isComparePreviewAbsent(raw) {
	const t = (raw ?? "").trim();
	return t === "" || t === "(없음)";
}
/**
* 한쪽 문서 기준 사람이 읽는 구역·쪽 (annotateDiffSectionPages 결과 + 스냅샷 직후 앵커).
* - 오른쪽 `added`: path가 오른쪽 문단이라 왼쪽에는 `contextOnLeft` 구역을 씀.
* - 왼쪽 `removed`: 오른쪽에는 `contextOnRight` 구역을 씀.
*/
function formatParagraphLocationForSide(item, side) {
	let sec;
	if (side === "left" && item.severity === "added") {
		if (!item.contextOnLeft) return null;
		sec = item.contextOnLeft.section;
	} else if (side === "right" && item.severity === "removed") {
		if (!item.contextOnRight) return null;
		sec = item.contextOnRight.section;
	} else sec = item.path.section;
	if (sec < 0) return null;
	const sectionPage = side === "left" ? item.leftSectionPage : item.rightSectionPage;
	if (sectionPage !== void 0 && sectionPage > 0) return `제 ${sec + 1}구역, ${sectionPage}쪽`;
	const anchor = side === "left" ? item.leftAnchor : item.rightAnchor;
	if (anchor) return `제 ${sec + 1}구역, ${anchor.pageIndex + 1}쪽`;
	return `제 ${sec + 1}구역`;
}
/** 비교 결과 목록·요약 줄 (좌/우 각각 채워지면 둘 다 표시) */
function formatDiffLocationCombined(item) {
	const L = formatParagraphLocationForSide(item, "left");
	const R = formatParagraphLocationForSide(item, "right");
	if (!L && !R) return null;
	if (L && R) return `좌 ${L}, 우 ${R}`;
	return L ?? R;
}
//#endregion
//#region src/compare/compare-debug.ts
/**
* 문서 비교 디버그 (밀림 / ID / 폴백 원인 추적).
*
* 켜는 방법(택일):
* - `localStorage.setItem('rhwp:compareDebug', '1')` 후 페이지 새로고침
* - URL에 `?compareDebug=1`
* - 콘솔에서 `globalThis.__RHWP_COMPARE_DEBUG__ = true`
*/
function isCompareDebugEnabled() {
	try {
		if (typeof globalThis !== "undefined" && globalThis.__RHWP_COMPARE_DEBUG__) return true;
		if (typeof window !== "undefined") {
			if (new URLSearchParams(window.location.search).get("compareDebug") === "1") return true;
			if (window.localStorage?.getItem("rhwp:compareDebug") === "1") return true;
		}
	} catch {}
	return false;
}
function compareDbg(...args) {
	if (!isCompareDebugEnabled()) return;
	console.log("[rhwp:compare]", ...args);
}
//#endregion
//#region src/compare/diff-engine.ts
/**
* HWP 문서 비교 엔진 — 문단 정렬(alignment), 문자 단위 diff, 표·도형·그림 등 컨트롤 diff를 한 모듈에서 처리한다.
*
* ── [용어] “밀림(shift)”
* 한쪽에 문단·표가 삽입되면 이후 문단의 `section`/`paragraph`/`globalIndex`가 통째로 밀린다.
* 텍스트는 내용 기반 정렬로 상쇄할 수 있으나, 컨트롤 키에 물리 위치가 남으면 표/도형이 “삭제+추가”로
* 쪼개져 보이는 문제가 생긴다. 이 파일은 (A) 문단 쪽 밀림 완화 (B) 정렬 결과를 컨트롤에 전달 두 축으로 대응한다.
*
* ── [도메인 분리: identity vs alignment]
* - **이력(같은 혈통)**: `stable_id`가 양쪽에 공유되면 `identity` 경로로 문단 1:1을 직접 잡는다(O(N) 수준).
* - **외부 문서(다른 혈통)**: 공유 sid가 없으므로 `alignment`만 사용한다. 유일·긴 문단과 섹션 제목류를
*   **글로벌 앵커**로 써 문서를 구간으로 쪼개고, 구간 안은 DP/그리디로 채운다.
*
* ── [문단 밀림 완화 — alignment 내부 계층]
* 1. **글로벌 앵커** (`buildAnchorPairs`, `fillSnapshotFromWasm`의 `isAnchorCandidate`)
*    - 시그니처가 좌·우 각각 한 번만 등장하는 문단만 앵커 후보.
*    - 길이·엔트로피 등 `isAnchorTextQualityOk`로 짧은 반복 문장을 걸러 오염 앵커를 막는다.
*    - `[테스트 N: …]` 같은 짧은 제목은 `isStructuralBlockTitleLine` 등으로 후보로 올리되,
*      `buildBothSidesUniqueTrimNorm`으로 **trim 본문이 양쪽 문서에서 정확히 한 번씩**일 때만 글로벌 앵커로 승인.
* 2. **구간 정렬** (`matchSegment` 재귀 트리)
*    - `buildUniqueSigPairsInSlices`: 구간 안에서만 시그니처 빈도를 세 **내부 Patience 핀**으로 쪼갠다.
*    - `tryMatchByNormHashPins`: 서명 핀이 없을 때 `normalizedText` 해시 토큰으로 거시 핀(DMP line-mode 유사).
*    - `matchSegmentDp` / `findLongestEqualSignatureRun` / `matchWindowedGreedy`: 셀 수·시간 한도에 따라 선택.
* 3. **상대 구조 근접** (`SegmentAnchorBoundary` + `runWithSegmentStructBase` + `isNearStructure`)
*    - 구간마다 직전 글로벌 앵커 쌍의 `globalIndex`를 베이스로 잡고, `|Δleft - Δright| ≤ 2`로 본다.
*    - 문서 맨 앞 구간은 베이스가 구간 **첫 문단**이다. 절대 인덱스만 보면 큰 밀림 직후 이웃 문단이
*      구조적으로 가깝다고 인정받지 못하는 문제를 줄인다.
* 4. **DP 비용** (`matchCost`, `getEffectiveSimilarity`, `softSimilarityThresholdForPair`)
*    - 유사도는 “전역 라벨”이 아니라 치환 비용·약매칭 방지용 가중치로만 쓴다.
*
* ── [컨트롤 밀림 완화]
* - 1차: `kind::key` 정확 일치(`sid:…` 우선).
* - 2차: **`buildRightToLeftParaMapFromAligned`** — `buildTextDiffs`가 만든 문단 정렬 `AlignedPair[]`에서
*   오른쪽 `section:paragraph` → 짝 왼쪽 문단 맵을 구축해 `buildControlDiffs`에 전달한다.
* - 3차: **`extractTablePatiencePins`** — 요약 키가 양쪽에서 각각 유일한 표를 슬롯보다 먼저 고정한다.
* - 4차: **`pairAlignmentSlotControls`** — 남은 컨트롤에 대해, 오른쪽 부모 문단의 맵상 짝 왼쪽 문단에 붙은
*   미매칭 컨트롤만 후보로 `scoreControlFallback + ALIGNMENT_CONTROL_SLOT_BONUS`로 짝을 찾는다.
* - 5차: `pairControlsFallback`(전역 탐욕, 임계 2.75).
*
* ── [단계적 비교(성능)]
* - 전 문단×문단 유사도 행렬 같은 O(N²) 전역 최적화는 하지 않는다.
* - 짝이 맞은 문단에만 `myersCharDiffSummary`(접두·접미 제거, Hirschberg, `CHAR_DIFF_*` 상한)를 적용한다.
*
* ── [튜닝 상수 — `// ─── 튜닝 상수` 블록]
* - 앵커·구간: ANCHOR_*, INTRA_UNIQUE_SIG_*, SEGMENT_DP_MAX, NORM_HASH_PIN_MIN_TOTAL_PARAS, HARD_SEGMENT_CELL_LIMIT,
*   ALIGNMENT_MAX_COMPUTE_MS, MAX_SEGMENT_RECURSION
* - 구조 근접·비용: NEAR_STRUCTURE_*, MATCH_SOFT_SIM_MIN, MATCH_COST_WEAK, WINDOW_SIZE, GREEDY_AMBIGUOUS_GAP
* - 컨트롤 슬롯: ALIGNMENT_CONTROL_SLOT_BONUS, ALIGNMENT_CONTROL_MIN_ADJUSTED_SCORE,
*   TABLE_SUMMARY_MISMATCH_PENALTY, TABLE_PAIR_SIM_NO_PENALTY, TABLE_PAIR_SIM_FULL_PENALTY
* - 후처리: PARA_SPLIT_JOIN_SIM_MIN, REMOVED_ADDED_*
* - 문자 요약: CHAR_DIFF_FULL_DP_MAX, CHAR_DIFF_TOTAL_MAX, CHAR_DIFF_CELL_HARD
*
* ── [입력 경로]
* - `buildSnapshotFromBytes`: 외부 파일 비교.
* - `buildSnapshotFromWasm`: 편집기 IR — 같은 세션 이력에서 sid 보존에 유리.
*
* ── [공개 진입점]
* - `compareSnapshots`: 전략 선택 → 본문 diff → 컨트롤 diff(맵 전달) → 필터·쪽번호·정렬.
* - `compareDocuments`: bytes 두 개를 스냅샷으로 만든 뒤 위와 동일.
*
* ── [유지보수]
* - 품질 이슈 시 compare-debug 로그 ① stable_id ② 전략 ③ 앵커를 함께 본다.
* - 본 파일은 `// ───` 섹션 구분으로 점프 검색이 가능하다.
*/
/** alignment 경로: 오른쪽 문단마다 왼쪽에서 고를 때의 탐색 반경(문단 개수) */
var WINDOW_SIZE = 32;
/** `buildAnchorPairs`: 시그니처가 같아도 너무 짧은 문단은 앵커 후보에서 제외(오탐 앵커 방지) */
var ANCHOR_MIN_TEXT_LEN = 20;
/** `[테스트 N: …]` 등 짧은 블록 제목을 앵커로 쓸 때 최소 글자 수(공백 제거 `trim` 기준) */
var STRUCTURAL_ANCHOR_MIN_LEN = 5;
/** 최상위 구간 `buildUniqueSigPairsInSlices` 최소 문단 길이 */
var INTRA_UNIQUE_SIG_MIN_TOP = 10;
/** 글로벌 앵커로 이미 자른 하위 구간에서 내부 유일 시그니처 핀의 최소 길이 */
var INTRA_UNIQUE_SIG_MIN_NESTED = 4;
/** 동일 서명 문단 쌍의 globalIndex 차가 이 값보다 크면 "문단 이동" 메타 후보로 본다 */
var MOVE_DISTANCE_THRESHOLD = 3;
/** 정렬이 (null,R앞)(L,R뒤)로 나온 쪼개기만: L≈R앞+R뒤일 때 R앞=변경·R뒤=추가로 재라벨 */
