/** 번호 형식 코드로 샘플 번호 문자열 생성 */
function formatNumber(num, fmt) {
	switch (fmt) {
		case NUM_FMT.DIGIT: return String(num);
		case NUM_FMT.CIRCLE_DIGIT: return num >= 1 && num <= 20 ? "①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳"[num - 1] : String(num);
		case NUM_FMT.ROMAN_UPPER: return toRoman(num);
		case NUM_FMT.ROMAN_LOWER: return toRoman(num).toLowerCase();
		case NUM_FMT.ALPHA_UPPER: return num >= 1 && num <= 26 ? String.fromCharCode(64 + num) : String(num);
		case NUM_FMT.ALPHA_LOWER: return num >= 1 && num <= 26 ? String.fromCharCode(96 + num) : String(num);
		case NUM_FMT.HANGUL_SYLLABLE:
		case NUM_FMT.HANGUL_MIXED: return num >= 1 && num <= 14 ? "가나다라마바사아자차카타파하"[num - 1] : String(num);
		case NUM_FMT.HANGUL_JAMO: return num >= 1 && num <= 14 ? "ㄱㄴㄷㄹㅁㅂㅅㅇㅈㅊㅋㅌㅍㅎ"[num - 1] : String(num);
		case NUM_FMT.HANJA: return num >= 1 && num <= 10 ? "一二三四五六七八九十"[num - 1] : String(num);
		default: return String(num);
	}
}
function toRoman(n) {
	const vals = [
		1e3,
		900,
		500,
		400,
		100,
		90,
		50,
		40,
		10,
		9,
		5,
		4,
		1
	];
	const syms = [
		"M",
		"CM",
		"D",
		"CD",
		"C",
		"XC",
		"L",
		"XL",
		"X",
		"IX",
		"V",
		"IV",
		"I"
	];
	let result = "";
	let num = n;
	for (let i = 0; i < vals.length; i++) while (num >= vals[i]) {
		result += syms[i];
		num -= vals[i];
	}
	return result;
}
/** 프리셋의 미리보기 텍스트 생성 (7수준) */
function generatePreview(preset, startNumber) {
	const lines = [];
	for (let level = 0; level < 7; level++) {
		const indent = "  ".repeat(level);
		const fmt = preset.levelFormats[level];
		const numStr = formatNumber(startNumber, preset.numberFormats[level]);
		const marker = fmt.replace(`^${level + 1}`, numStr);
		lines.push(`${indent}수준 ${level + 1}: ${marker}`);
	}
	return lines.join("\n");
}
