//#region src/ui/new-number-dialog.ts
var NewNumberDialog = class extends ModalDialog {
	services;
	wasm;
	eventBus;
	cursorPos;
	numInput;
	constructor(wasm, eventBus, pos, services) {
		super("새 번호로 시작", 300);
		this.services = services;
		this.wasm = wasm;
		this.eventBus = eventBus;
		this.cursorPos = pos;
	}
	createBody() {
		const body = document.createElement("div");
		body.style.padding = "16px";
		const row = document.createElement("div");
		row.style.display = "flex";
		row.style.alignItems = "center";
		row.style.gap = "8px";
		const label = document.createElement("label");
		label.textContent = "시작 번호:";
		label.style.whiteSpace = "nowrap";
		this.numInput = document.createElement("input");
		this.numInput.type = "number";
		this.numInput.min = "1";
		this.numInput.max = "65535";
		this.numInput.value = "1";
		this.numInput.style.width = "80px";
		this.numInput.style.padding = "4px 8px";
		row.appendChild(label);
		row.appendChild(this.numInput);
		body.appendChild(row);
		return body;
	}
	show() {
		super.show();
		setTimeout(() => {
			this.numInput.focus();
			this.numInput.select();
		}, 50);
	}
	onConfirm() {
		const num = parseInt(this.numInput.value, 10);
		if (isNaN(num) || num < 1 || num > 65535) return false;
		const apply = () => this.wasm.insertNewNumber(this.cursorPos.sec, this.cursorPos.para, this.cursorPos.offset, num);
		return applyThroughRouter({
			services: this.services,
			label: "NewNumberDialog",
			operationType: "insertNewNumber",
			operation: (ih) => {
				apply();
				return ih.getCursorPosition();
			},
			fallback: () => {
				apply();
				this.eventBus.emit("document-changed");
			}
		});
	}
};
