//#region src/ui/font-set-edit-dialog.ts
/**
* 대표 글꼴 추가/편집 대화상자
*
* 이름 입력 + 7개 언어별 글꼴 드롭다운
*/
/** 웹폰트 목록 (중복 제거 + 정렬) */
function getWebFonts() {
	const unique = /* @__PURE__ */ new Set();
	for (const name of REGISTERED_FONTS) unique.add(name);
	[
		"serif",
		"sans-serif",
		"monospace"
	].forEach((f) => unique.add(f));
	return Array.from(unique).sort((a, b) => a.localeCompare(b, "ko"));
}
var FontSetEditDialog = class extends ModalDialog {
	nameInput;
	langSelects = [];
	editTarget;
	onApply;
	constructor(editTarget, onApply) {
		super(editTarget ? "대표 글꼴 편집하기" : "대표 글꼴 추가하기", 400);
		this.editTarget = editTarget;
		this.onApply = onApply;
	}
	createBody() {
		const body = document.createElement("div");
		body.className = "fse-body";
		const webFonts = getWebFonts();
		const localFonts = getLocalFonts();
		const langKeys = [
			"korean",
			"english",
			"chinese",
			"japanese",
			"other",
			"symbol",
			"user"
		];
		const nameRow = document.createElement("div");
		nameRow.className = "dialog-row fse-row";
		const nameLabel = document.createElement("label");
		nameLabel.className = "dialog-label fse-label";
		nameLabel.textContent = "대표 글꼴 이름";
		this.nameInput = document.createElement("input");
		this.nameInput.type = "text";
		this.nameInput.className = "dialog-input fse-name-input";
		this.nameInput.placeholder = "예: 나의 글꼴 세트";
		if (this.editTarget) this.nameInput.value = this.editTarget.name;
		nameRow.appendChild(nameLabel);
		nameRow.appendChild(this.nameInput);
		body.appendChild(nameRow);
		const sep = document.createElement("hr");
		sep.className = "fse-sep";
		body.appendChild(sep);
		LANG_LABELS.forEach((label, i) => {
			const row = document.createElement("div");
			row.className = "dialog-row fse-row";
			const lbl = document.createElement("label");
			lbl.className = "dialog-label fse-label";
			lbl.textContent = label;
			const select = document.createElement("select");
			select.className = "dialog-select fse-select";
			const webGroup = document.createElement("optgroup");
			webGroup.label = "웹 글꼴";
			for (const fontName of webFonts) {
				const opt = document.createElement("option");
				opt.value = fontName;
				opt.textContent = fontName;
				webGroup.appendChild(opt);
			}
			select.appendChild(webGroup);
			if (localFonts.length > 0) {
				const localGroup = document.createElement("optgroup");
				localGroup.label = "로컬 글꼴";
				for (const fontName of localFonts) {
					const opt = document.createElement("option");
					opt.value = fontName;
					opt.textContent = fontName;
					localGroup.appendChild(opt);
				}
				select.appendChild(localGroup);
			}
			if (this.editTarget) select.value = this.editTarget[langKeys[i]];
			else select.value = "함초롬바탕";
			this.langSelects.push(select);
			row.appendChild(lbl);
			row.appendChild(select);
			body.appendChild(row);
		});
		return body;
	}
	onConfirm() {
		const name = this.nameInput.value.trim();
		if (!name) {
			alert("대표 글꼴 이름을 입력하세요.");
			return;
		}
		const fs = {
			name,
			korean: this.langSelects[0].value,
			english: this.langSelects[1].value,
			chinese: this.langSelects[2].value,
			japanese: this.langSelects[3].value,
			other: this.langSelects[4].value,
			symbol: this.langSelects[5].value,
			user: this.langSelects[6].value
		};
		this.onApply(fs);
	}
};
//#endregion
//#region src/ui/font-set-dialog.ts
/**
* 대표 글꼴 등록하기 대화상자
*
* 내장 프리셋 + 사용자 정의 대표 글꼴 목록을 표시하고
* 추가/편집/삭제 기능을 제공한다.
*/
var FontSetDialog = class extends ModalDialog {
	listEl;
	infoEl;
	selectedIndex = -1;
	editBtn;
	deleteBtn;
	constructor() {
		super("대표 글꼴 등록하기", 520);
	}
	createBody() {
		const body = document.createElement("div");
		body.className = "fs-body";
		const toolbar = document.createElement("div");
		toolbar.className = "fs-toolbar";
		const addBtn = document.createElement("button");
		addBtn.className = "dialog-btn fs-icon-btn";
		addBtn.title = "대표 글꼴 추가하기";
		addBtn.textContent = "+";
		addBtn.addEventListener("click", () => this.onAdd());
		this.editBtn = document.createElement("button");
		this.editBtn.className = "dialog-btn fs-icon-btn";
		this.editBtn.title = "대표 글꼴 편집하기";
		this.editBtn.textContent = "✎";
		this.editBtn.disabled = true;
		this.editBtn.addEventListener("click", () => this.onEdit());
		this.deleteBtn = document.createElement("button");
		this.deleteBtn.className = "dialog-btn fs-icon-btn";
		this.deleteBtn.title = "대표 글꼴 지우기";
		this.deleteBtn.textContent = "−";
		this.deleteBtn.disabled = true;
		this.deleteBtn.addEventListener("click", () => this.onDelete());
		toolbar.appendChild(addBtn);
		toolbar.appendChild(this.editBtn);
		toolbar.appendChild(this.deleteBtn);
		body.appendChild(toolbar);
		const content = document.createElement("div");
		content.className = "fs-content";
		this.listEl = document.createElement("div");
		this.listEl.className = "fs-list";
		content.appendChild(this.listEl);
		this.infoEl = document.createElement("div");
		this.infoEl.className = "fs-info";
		content.appendChild(this.infoEl);
		body.appendChild(content);
		this.refreshList();
		return body;
	}
	refreshList() {
		this.listEl.replaceChildren();
		const builtins = BUILTIN_FONT_SETS;
		const customs = userSettings.getUserFontSets();
		builtins.forEach((fs, i) => {
			const item = this.createListItem(fs, -(i + 1), true);
			this.listEl.appendChild(item);
		});
		customs.forEach((fs, i) => {
			const item = this.createListItem(fs, i, false);
			this.listEl.appendChild(item);
		});
		this.selectedIndex = -1;
		this.updateButtons();
		this.showInfo(null);
	}
	createListItem(fs, index, isBuiltin) {
		const item = document.createElement("div");
		item.className = "fs-list-item";
		if (isBuiltin) item.classList.add("fs-builtin");
		item.dataset.index = String(index);
		const nameSpan = document.createElement("span");
		nameSpan.className = "fs-item-name";
		nameSpan.textContent = fs.name;
		item.appendChild(nameSpan);
		if (isBuiltin) {
			const badge = document.createElement("span");
			badge.className = "fs-badge";
			badge.textContent = "내장";
			item.appendChild(badge);
		}
		item.addEventListener("click", () => {
			this.listEl.querySelectorAll(".fs-list-item").forEach((el) => el.classList.remove("selected"));
			item.classList.add("selected");
			this.selectedIndex = index;
			this.updateButtons();
			this.showInfo(fs);
		});
		return item;
	}
	updateButtons() {
		const isCustom = this.selectedIndex >= 0;
		this.editBtn.disabled = !isCustom;
		this.deleteBtn.disabled = !isCustom;
	}
	showInfo(fs) {
		this.infoEl.replaceChildren();
		if (!fs) {
			const empty = document.createElement("div");
			empty.className = "fs-info-empty";
			empty.textContent = "대표 글꼴을 선택하세요";
			this.infoEl.appendChild(empty);
			return;
		}
		const name = document.createElement("div");
		name.className = "fs-info-name";
		name.textContent = fs.name;
		this.infoEl.appendChild(name);
		LANG_LABELS.forEach((label, i) => {
			const val = UserSettingsService_getFontByLang(fs, i);
			const row = document.createElement("div");
			row.className = "fs-info-row";
			const labelSpan = document.createElement("span");
			labelSpan.className = "fs-info-label";
			labelSpan.textContent = label;
			const valueSpan = document.createElement("span");
			valueSpan.className = "fs-info-value";
			valueSpan.textContent = val;
			row.appendChild(labelSpan);
			row.appendChild(valueSpan);
			this.infoEl.appendChild(row);
		});
	}
	onAdd() {
		new FontSetEditDialog(null, (newFs) => {
			if (userSettings.addFontSet(newFs)) this.refreshList();
			else alert("같은 이름의 대표 글꼴이 이미 등록되어 있습니다.");
		}).show();
	}
	onEdit() {
		if (this.selectedIndex < 0) return;
		const fs = userSettings.getUserFontSets()[this.selectedIndex];
		if (!fs) return;
		new FontSetEditDialog(fs, (updated) => {
			if (userSettings.getAllFontSets().some((s, i) => {
				if (i === BUILTIN_FONT_SETS.length + this.selectedIndex) return false;
				return s.name === updated.name;
			})) {
				alert("같은 이름의 대표 글꼴이 이미 등록되어 있습니다.");
				return;
			}
			userSettings.updateFontSet(this.selectedIndex, updated);
			this.refreshList();
		}).show();
	}
	onDelete() {
		if (this.selectedIndex < 0) return;
		const fs = userSettings.getUserFontSets()[this.selectedIndex];
		if (!fs) return;
		if (confirm(`선택한 대표 글꼴 "${fs.name}"을(를) 지울까요?`)) {
			userSettings.removeFontSet(this.selectedIndex);
			this.refreshList();
		}
	}
	onConfirm() {}
};
/** UserSettingsService.getFontByLang 정적 호출 헬퍼 */
function UserSettingsService_getFontByLang(fs, langIndex) {
	return fs[[
		"korean",
		"english",
		"chinese",
		"japanese",
		"other",
		"symbol",
		"user"
	][langIndex] ?? "korean"];
}
//#endregion
//#region src/ui/options-dialog.ts
/**
* 환경 설정 대화상자 (도구 > 환경 설정)
*
* 탭 구조: [글꼴] (향후 [편집], [보기] 등 탭 추가 가능)
*/
var OptionsDialog = class extends ModalDialog {
	eventBus;
	showRecentCheck;
	recentCountInput;
	recoveryEnabledCheck;
	recoveryIntervalInput;
	idleSaveEnabledCheck;
	idleDelayInput;
	pdfPrintGuidanceCheck;
	constructor(eventBus) {
		super("환경 설정", 480);
		this.eventBus = eventBus;
	}
	createBody() {
		const body = document.createElement("div");
		body.className = "opt-body";
		const tabs = document.createElement("div");
		tabs.className = "dialog-tabs";
		const fontTab = document.createElement("button");
		fontTab.className = "dialog-tab active";
		fontTab.textContent = "글꼴";
		fontTab.dataset.tab = "font";
		tabs.appendChild(fontTab);
		const fileTab = document.createElement("button");
		fileTab.className = "dialog-tab";
		fileTab.textContent = "파일";
		fileTab.dataset.tab = "file";
		tabs.appendChild(fileTab);
		body.appendChild(tabs);
		const fontPanel = this.createFontPanel();
		fontPanel.className = "dialog-tab-panel opt-tab-panel active";
		fontPanel.dataset.tab = "font";
		body.appendChild(fontPanel);
		const filePanel = this.createFilePanel();
		filePanel.className = "dialog-tab-panel opt-tab-panel";
		filePanel.dataset.tab = "file";
		body.appendChild(filePanel);
		tabs.addEventListener("click", (e) => {
			const btn = e.target.closest(".dialog-tab");
			if (!btn) return;
			const tabId = btn.dataset.tab;
			tabs.querySelectorAll(".dialog-tab").forEach((t) => t.classList.remove("active"));
			body.querySelectorAll(".dialog-tab-panel").forEach((p) => p.classList.remove("active"));
			btn.classList.add("active");
			body.querySelector(`.dialog-tab-panel[data-tab="${tabId}"]`)?.classList.add("active");
		});
		return body;
	}
	createFontPanel() {
		const panel = document.createElement("div");
		const fs = userSettings.getFontSettings();
		const viewSection = document.createElement("div");
		viewSection.className = "dialog-section";
		const viewTitle = document.createElement("div");
		viewTitle.className = "dialog-section-title";
		viewTitle.textContent = "글꼴 보기";
		viewSection.appendChild(viewTitle);
		const recentRow = document.createElement("div");
		recentRow.className = "dialog-row opt-row";
		this.showRecentCheck = document.createElement("input");
		this.showRecentCheck.type = "checkbox";
		this.showRecentCheck.id = "opt-show-recent";
		this.showRecentCheck.checked = fs.showRecentFonts;
		const recentLabel = document.createElement("label");
		recentLabel.htmlFor = "opt-show-recent";
		recentLabel.textContent = "최근에 사용한 글꼴 보이기";
		this.recentCountInput = document.createElement("input");
		this.recentCountInput.type = "number";
		this.recentCountInput.className = "dialog-input opt-count-input";
		this.recentCountInput.min = "1";
		this.recentCountInput.max = "5";
		this.recentCountInput.value = String(fs.recentFontCount);
		const countLabel = document.createElement("span");
		countLabel.className = "opt-count-label";
		countLabel.textContent = "개";
		recentRow.appendChild(this.showRecentCheck);
		recentRow.appendChild(recentLabel);
		recentRow.appendChild(this.recentCountInput);
		recentRow.appendChild(countLabel);
		viewSection.appendChild(recentRow);
		panel.appendChild(viewSection);
		const fontSetSection = document.createElement("div");
		fontSetSection.className = "dialog-section";
		const fontSetTitle = document.createElement("div");
		fontSetTitle.className = "dialog-section-title";
		fontSetTitle.textContent = "대표 글꼴 등록";
		fontSetSection.appendChild(fontSetTitle);
		const fontSetDesc = document.createElement("p");
		fontSetDesc.className = "opt-desc";
		fontSetDesc.textContent = "대표 글꼴은 각 언어별 글꼴을 짝지어 한 번에 적용하는 글꼴 세트입니다.";
		fontSetSection.appendChild(fontSetDesc);
		const fontSetBtn = document.createElement("button");
		fontSetBtn.className = "dialog-btn opt-fontset-btn";
		fontSetBtn.textContent = "대표 글꼴 등록하기";
		fontSetBtn.addEventListener("click", () => {
			new FontSetDialog().show();
		});
		fontSetSection.appendChild(fontSetBtn);
		panel.appendChild(fontSetSection);
		const localSection = document.createElement("div");
		localSection.className = "dialog-section";
		const localTitle = document.createElement("div");
		localTitle.className = "dialog-section-title";
		localTitle.textContent = "로컬 글꼴";
		localSection.appendChild(localTitle);
		const localDesc = document.createElement("p");
		localDesc.className = "opt-desc";
		localDesc.textContent = "PC에 설치된 글꼴을 감지하여 글꼴 목록에 추가합니다. (Chrome/Edge 전체 감지 지원, Firefox는 문서 로드 시 필요한 글꼴만 확인)";
		localSection.appendChild(localDesc);
		const localRow = document.createElement("div");
		localRow.className = "dialog-row opt-row opt-local-actions";
		const localBtn = document.createElement("button");
		localBtn.className = "dialog-btn opt-fontset-btn";
		localBtn.textContent = "로컬 글꼴 감지하기";
		const resetBtn = document.createElement("button");
		resetBtn.className = "dialog-btn opt-fontset-btn";
		resetBtn.textContent = "감지 결과 초기화";
		const localStatus = document.createElement("p");
		localStatus.className = "opt-local-status";
		const updateLocalStatus = (message) => {
			const state = getLocalFontState();
			localStatus.textContent = message ?? formatLocalFontStatus(state);
			resetBtn.disabled = !state.stored;
			localBtn.textContent = state.stored ? "로컬 글꼴 재감지" : "로컬 글꼴 감지하기";
		};
		updateLocalStatus("감지 결과 확인 중...");
		loadStoredLocalFonts().then(() => updateLocalStatus(), () => updateLocalStatus("저장된 감지 결과를 확인하지 못했습니다."));
		localBtn.addEventListener("click", async () => {
			if (!isLocalFontAccessSupported()) {
				localStatus.textContent = getLocalFontState().method === "font-presence-probe" ? "이 브라우저는 전체 로컬 글꼴 목록 감지를 지원하지 않습니다. 문서를 열 때 필요한 글꼴만 확인합니다." : "이 브라우저는 로컬 글꼴 감지를 지원하지 않습니다.";
				return;
			}
			localBtn.disabled = true;
			resetBtn.disabled = true;
			localStatus.textContent = "감지 중...";
			try {
				const fonts = await detectLocalFonts({ force: true });
				updateLocalStatus(`${fonts.length}개 로컬 글꼴을 감지하고 저장했습니다.`);
				this.eventBus?.emit("local-fonts-changed", {
					fonts,
					source: "options-dialog"
				});
			} catch (error) {
				updateLocalStatus(describeLocalFontDetectionError(error));
			}
			localBtn.disabled = false;
		});
		resetBtn.addEventListener("click", async () => {
			localBtn.disabled = true;
			resetBtn.disabled = true;
			localStatus.textContent = "감지 결과 초기화 중...";
			try {
				await clearStoredLocalFonts();
				updateLocalStatus("저장된 로컬 글꼴 감지 결과를 삭제했습니다.");
				this.eventBus?.emit("local-fonts-changed", {
					fonts: [],
					source: "options-dialog-clear"
				});
			} catch {
				updateLocalStatus("저장된 감지 결과를 삭제하지 못했습니다.");
			}
			localBtn.disabled = false;
		});
		localRow.appendChild(localBtn);
		localRow.appendChild(resetBtn);
		localSection.appendChild(localRow);
		localSection.appendChild(localStatus);
		panel.appendChild(localSection);
		return panel;
	}
	createFilePanel() {
		const panel = document.createElement("div");
		const autosave = userSettings.getAutosaveSettings();
		const dialogSettings = userSettings.getDialogSettings();
		const saveSection = document.createElement("div");
		saveSection.className = "dialog-section";
		const saveTitle = document.createElement("div");
		saveTitle.className = "dialog-section-title";
		saveTitle.textContent = "복구용 임시 파일 자동 저장";
		saveSection.appendChild(saveTitle);
		const desc = document.createElement("p");
		desc.className = "opt-desc";
		desc.textContent = "대형 문서는 자동저장 시 전체 HWP 복구본을 만들기 때문에 간격을 길게 두면 편집 중 멈춤을 줄일 수 있습니다.";
		saveSection.appendChild(desc);
		this.recoveryEnabledCheck = document.createElement("input");
		this.recoveryEnabledCheck.type = "checkbox";
		this.recoveryEnabledCheck.id = "opt-recovery-enabled";
		this.recoveryEnabledCheck.checked = autosave.recoveryEnabled;
		this.recoveryIntervalInput = document.createElement("input");
		this.recoveryIntervalInput.type = "number";
		this.recoveryIntervalInput.className = "dialog-input opt-interval-input";
		this.recoveryIntervalInput.min = "1";
		this.recoveryIntervalInput.max = "120";
		this.recoveryIntervalInput.value = String(autosave.recoveryIntervalMinutes);
		saveSection.appendChild(createAutosaveNumberRow({
			checkbox: this.recoveryEnabledCheck,
			labelText: "복구용 자동 저장",
			numberInput: this.recoveryIntervalInput,
			unitText: "분"
		}));
		this.idleSaveEnabledCheck = document.createElement("input");
		this.idleSaveEnabledCheck.type = "checkbox";
		this.idleSaveEnabledCheck.id = "opt-idle-save-enabled";
		this.idleSaveEnabledCheck.checked = autosave.idleSaveEnabled;
		this.idleDelayInput = document.createElement("input");
		this.idleDelayInput.type = "number";
		this.idleDelayInput.className = "dialog-input opt-interval-input";
		this.idleDelayInput.min = "5";
		this.idleDelayInput.max = "600";
		this.idleDelayInput.value = String(autosave.idleDelaySeconds);
		saveSection.appendChild(createAutosaveNumberRow({
			checkbox: this.idleSaveEnabledCheck,
			labelText: "쉴 때 자동 저장",
			numberInput: this.idleDelayInput,
			unitText: "초"
		}));
		const syncDisabled = () => {
			this.recoveryIntervalInput.disabled = !this.recoveryEnabledCheck.checked;
			this.idleDelayInput.disabled = !this.idleSaveEnabledCheck.checked;
		};
		this.recoveryEnabledCheck.addEventListener("change", syncDisabled);
		this.idleSaveEnabledCheck.addEventListener("change", syncDisabled);
		syncDisabled();
		panel.appendChild(saveSection);
		const pdfSection = document.createElement("div");
		pdfSection.className = "dialog-section";
		const pdfTitle = document.createElement("div");
		pdfTitle.className = "dialog-section-title";
		pdfTitle.textContent = "PDF 저장";
		pdfSection.appendChild(pdfTitle);
		const pdfDesc = document.createElement("p");
		pdfDesc.className = "opt-desc";
		pdfDesc.textContent = "안내를 끄면 PDF로 저장을 선택하는 즉시 문서 준비가 시작됩니다. 준비 진행률과 오류는 계속 표시됩니다.";
		pdfSection.appendChild(pdfDesc);
		const pdfRow = document.createElement("div");
		pdfRow.className = "dialog-row opt-row";
		this.pdfPrintGuidanceCheck = document.createElement("input");
		this.pdfPrintGuidanceCheck.type = "checkbox";
		this.pdfPrintGuidanceCheck.id = "opt-pdf-print-guidance";
		this.pdfPrintGuidanceCheck.checked = dialogSettings.showPdfPrintGuidance;
		const pdfLabel = document.createElement("label");
		pdfLabel.htmlFor = "opt-pdf-print-guidance";
		pdfLabel.textContent = "PDF로 저장할 때 저장 방법 안내 표시";
		pdfRow.append(this.pdfPrintGuidanceCheck, pdfLabel);
		pdfSection.appendChild(pdfRow);
		panel.appendChild(pdfSection);
		return panel;
	}
	onConfirm() {
		const count = Math.min(5, Math.max(1, parseInt(this.recentCountInput.value) || 3));
		userSettings.updateFontSettings({
			showRecentFonts: this.showRecentCheck.checked,
			recentFontCount: count
		});
		userSettings.updateAutosaveSettings({
			recoveryEnabled: this.recoveryEnabledCheck.checked,
			recoveryIntervalMinutes: clampInteger(this.recoveryIntervalInput.value, 10, 1, 120),
			idleSaveEnabled: this.idleSaveEnabledCheck.checked,
			idleDelaySeconds: clampInteger(this.idleDelayInput.value, 10, 5, 600)
		});
		userSettings.setShowPdfPrintGuidance(this.pdfPrintGuidanceCheck.checked);
		this.eventBus?.emit("autosave-settings-changed", { source: "options-dialog" });
	}
};
function createAutosaveNumberRow(options) {
	const row = document.createElement("div");
	row.className = "dialog-row opt-row opt-autosave-row";
	const label = document.createElement("label");
	label.htmlFor = options.checkbox.id;
	label.textContent = options.labelText;
	const unit = document.createElement("span");
	unit.className = "opt-count-label";
	unit.textContent = options.unitText;
	row.appendChild(options.checkbox);
	row.appendChild(label);
	row.appendChild(options.numberInput);
	row.appendChild(unit);
	return row;
}
function clampInteger(value, fallback, min, max) {
	const parsed = Number.parseInt(value, 10);
	if (!Number.isFinite(parsed)) return fallback;
	return Math.min(max, Math.max(min, parsed));
}
function formatLocalFontStatus(state) {
	if (state.lastError) return `저장소 접근 실패: ${state.lastError}`;
	if (!state.stored) {
		if (state.method === "font-presence-probe") return "저장된 감지 결과가 없습니다. Firefox에서는 문서를 열 때 필요한 글꼴만 확인합니다.";
		if (!state.supported) return "이 브라우저는 로컬 글꼴 감지를 지원하지 않습니다.";
		return "저장된 감지 결과가 없습니다.";
	}
	const detectedAt = formatDetectedAt(state.detectedAt);
	const dateSuffix = detectedAt ? ` · ${detectedAt}` : "";
	if (state.source === "font-presence-probe") return `문서별 확인 결과 저장됨: 사용 가능 ${state.count}개 / 확인한 글꼴 ${state.checkedFamilies.length}개${dateSuffix}`;
	return `전체 로컬 글꼴 감지 결과 저장됨: ${state.count}개${dateSuffix}`;
}
function formatDetectedAt(value) {
	if (!value) return "";
	const date = new Date(value);
	if (Number.isNaN(date.getTime())) return "";
	const pad = (n) => String(n).padStart(2, "0");
	return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
function describeLocalFontDetectionError(error) {
	const name = typeof error === "object" && error !== null && "name" in error ? String(error.name ?? "") : "";
	const normalized = `${name} ${error instanceof Error ? error.message : String(error ?? "")}`.toLowerCase();
	if (name === "NotAllowedError" || normalized.includes("permission") || normalized.includes("denied")) return "로컬 글꼴 접근 권한이 허용되지 않았습니다. 브라우저 권한 설정에서 허용한 뒤 다시 시도해 주세요.";
	return "글꼴 감지에 실패했습니다. 웹 대체 글꼴로 계속 사용할 수 있습니다.";
}
