//#region src/command/pwa-file-handling.ts
async function readLaunchFileFromHandle(handle) {
	const file = await handle.getFile();
	return {
		name: file.name,
		bytes: new Uint8Array(await file.arrayBuffer())
	};
}
async function handlePwaLaunchFiles(params, callbacks) {
	const handles = params.files ?? [];
	if (handles.length === 0) return;
	if (handles.length > 1) callbacks.notifyMultipleFiles?.(handles.length);
	const handle = handles[0];
	if (!isSupportedDocumentFileName(handle.name)) {
		callbacks.notifyUnsupportedFile(handle.name);
		return;
	}
	try {
		const { bytes, name } = await readLaunchFileFromHandle(handle);
		if (!isSupportedDocumentFileName(name)) {
			callbacks.notifyUnsupportedFile(name);
			return;
		}
		callbacks.openDocumentBytes({
			bytes,
			fileName: name,
			fileHandle: handle,
			skipUnsavedGuard: false
		});
	} catch (error) {
		callbacks.notifyError(error);
	}
}
function installPwaFileHandling(windowLike, callbacks) {
	if (!windowLike.launchQueue?.setConsumer) return false;
	windowLike.launchQueue.setConsumer((params) => {
		handlePwaLaunchFiles(params, callbacks);
	});
	return true;
}
//#endregion
//#region src/ui/context-menu.ts
/**
* 우클릭 컨텍스트 메뉴
*
* - show()로 화면 좌표에 메뉴 표시
* - CommandDispatcher 연동: canExecute 체크로 비활성 항목 표시
* - ESC / 외부 클릭으로 닫기
*/
var ContextMenu = class {
	dispatcher;
	registry;
	el = null;
	escHandler = null;
	outsideHandler = null;
	constructor(dispatcher, registry) {
		this.dispatcher = dispatcher;
		this.registry = registry;
	}
	/** clientX/Y에 메뉴를 표시한다 */
	show(x, y, items) {
		this.hide();
		const menu = document.createElement("div");
		menu.className = "context-menu";
		for (const item of items) {
			if (item.type === "separator") {
				const sep = document.createElement("div");
				sep.className = "md-sep";
				menu.appendChild(sep);
				continue;
			}
			const cmdId = item.commandId;
			const def = this.registry.get(cmdId);
			if (!def) continue;
			const row = document.createElement("div");
			row.className = "md-item";
			row.dataset.cmd = cmdId;
			if (!this.dispatcher.isEnabled(cmdId)) row.classList.add("disabled");
			const labelSpan = document.createTextNode(item.label ?? def.label);
			row.appendChild(labelSpan);
			if (def.shortcutLabel) {
				const shortcut = document.createElement("span");
				shortcut.className = "md-shortcut";
				shortcut.textContent = formatShortcutLabel(def.shortcutLabel);
				row.appendChild(shortcut);
			}
			row.addEventListener("click", (e) => {
				e.stopPropagation();
				if (row.classList.contains("disabled")) return;
				this.dispatcher.dispatch(cmdId);
				this.hide();
			});
			menu.appendChild(row);
		}
		document.body.appendChild(menu);
		this.el = menu;
		const rect = menu.getBoundingClientRect();
		const vw = window.innerWidth;
		const vh = window.innerHeight;
		if (x + rect.width > vw) x = vw - rect.width - 2;
		if (y + rect.height > vh) y = vh - rect.height - 2;
		if (x < 0) x = 0;
		if (y < 0) y = 0;
		menu.style.left = `${x}px`;
		menu.style.top = `${y}px`;
		this.escHandler = (e) => {
			if (e.key === "Escape") {
				e.preventDefault();
				this.hide();
			}
		};
		document.addEventListener("keydown", this.escHandler, true);
		requestAnimationFrame(() => {
			this.outsideHandler = (e) => {
				if (this.el && !this.el.contains(e.target)) this.hide();
			};
			document.addEventListener("mousedown", this.outsideHandler, true);
		});
	}
	/** 메뉴를 닫는다 */
	hide() {
		if (this.escHandler) {
			document.removeEventListener("keydown", this.escHandler, true);
			this.escHandler = null;
		}
		if (this.outsideHandler) {
			document.removeEventListener("mousedown", this.outsideHandler, true);
			this.outsideHandler = null;
		}
		this.el?.remove();
		this.el = null;
	}
	/** 메뉴가 열려있는가? */
	get isOpen() {
		return this.el !== null;
	}
	dispose() {
		this.hide();
	}
};
//#endregion
//#region src/ui/command-palette.ts
/**
* `/` 커맨드 팔레트
*
* 편집 영역에서 `/` 키를 누르면 열리는 검색형 커맨드 실행창.
* Notion/Linear/GitHub 패턴: 한글/영문 레이블 + 단축키로 필터링.
*/
var CommandPalette = class {
	registry;
	dispatcher;
	overlay = null;
	input = null;
	list = null;
	items = [];
	selectedIdx = 0;
	captureHandler = null;
	constructor(registry, dispatcher) {
		this.registry = registry;
		this.dispatcher = dispatcher;
	}
	/** 팔레트를 열고 검색 입력에 포커스 */
	open() {
		if (this.overlay) return;
		this.items = this.buildItems();
		this.selectedIdx = 0;
		this.overlay = document.createElement("div");
		this.overlay.className = "cp-overlay";
		const panel = document.createElement("div");
		panel.className = "cp-panel";
		const inputWrap = document.createElement("div");
		inputWrap.className = "cp-input-wrap";
		const slash = document.createElement("span");
		slash.className = "cp-slash";
		slash.textContent = "/";
		this.input = document.createElement("input");
		this.input.type = "text";
		this.input.className = "cp-input";
		this.input.placeholder = "커맨드 검색...";
		this.input.autocomplete = "off";
		this.input.spellcheck = false;
		inputWrap.appendChild(slash);
		inputWrap.appendChild(this.input);
		panel.appendChild(inputWrap);
		this.list = document.createElement("div");
		this.list.className = "cp-list";
		panel.appendChild(this.list);
		this.overlay.appendChild(panel);
		document.body.appendChild(this.overlay);
		this.renderList(this.items);
		this.input.addEventListener("input", () => {
			this.selectedIdx = 0;
			const filtered = this.filter(this.input.value);
			this.renderList(filtered);
		});
		this.captureHandler = (e) => {
			if (e.key === "Escape") {
				e.preventDefault();
				e.stopPropagation();
				this.close();
				return;
			}
			if (e.key === "ArrowDown") {
				e.preventDefault();
				e.stopPropagation();
				this.moveSelection(1);
				return;
			}
			if (e.key === "ArrowUp") {
				e.preventDefault();
				e.stopPropagation();
				this.moveSelection(-1);
				return;
			}
			if (e.key === "Enter") {
				e.preventDefault();
				e.stopPropagation();
				this.executeSelected();
				return;
			}
			e.stopPropagation();
		};
		document.addEventListener("keydown", this.captureHandler, true);
		this.overlay.addEventListener("mousedown", (e) => {
			if (e.target === this.overlay) this.close();
		});
		this.input.focus();
	}
	close() {
		if (this.captureHandler) {
			document.removeEventListener("keydown", this.captureHandler, true);
			this.captureHandler = null;
		}
		this.overlay?.remove();
		this.overlay = null;
		this.input = null;
		this.list = null;
	}
	isOpen() {
		return this.overlay !== null;
	}
	/** 팔레트에 노출할 커맨드 목록 구성 (disabled 제외) */
	buildItems() {
		const all = [];
		for (const id of this.registry.getAllIds()) {
			const def = this.registry.get(id);
			if (def.canExecute) {}
			all.push(def);
		}
		return all;
	}
	/** 검색어로 필터링 */
	filter(query) {
		const q = query.trim().toLowerCase();
		if (!q) return this.items;
		return this.items.filter((def) => {
			if (def.label.toLowerCase().includes(q)) return true;
			if (def.id.toLowerCase().includes(q)) return true;
			if (def.shortcutLabel && (def.shortcutLabel.toLowerCase().includes(q) || formatShortcutLabel(def.shortcutLabel).toLowerCase().includes(q))) return true;
			return false;
		});
	}
	renderList(filtered) {
		if (!this.list) return;
		this.list.replaceChildren();
		if (filtered.length === 0) {
			const empty = document.createElement("div");
			empty.className = "cp-empty";
			empty.textContent = "검색 결과 없음";
			this.list.appendChild(empty);
			return;
		}
		filtered.forEach((def, idx) => {
			const row = document.createElement("div");
			row.className = "cp-item" + (idx === this.selectedIdx ? " cp-item--selected" : "");
			row.dataset.idx = String(idx);
			const labelEl = document.createElement("span");
			labelEl.className = "cp-item-label";
			labelEl.textContent = def.label;
			row.appendChild(labelEl);
			if (def.shortcutLabel) {
				const kbd = document.createElement("span");
				kbd.className = "cp-item-shortcut";
				kbd.textContent = formatShortcutLabel(def.shortcutLabel);
				row.appendChild(kbd);
			}
			row.addEventListener("mousedown", (e) => {
				e.preventDefault();
				this.selectedIdx = idx;
				this.executeSelected(filtered);
			});
			row.addEventListener("mousemove", () => {
				this.selectedIdx = idx;
				this.updateSelection(filtered.length);
			});
			this.list.appendChild(row);
		});
		this.scrollToSelected();
	}
	moveSelection(delta) {
		if (!this.list) return;
		const count = this.list.querySelectorAll(".cp-item").length;
		if (count === 0) return;
		this.selectedIdx = (this.selectedIdx + delta + count) % count;
		this.updateSelection(count);
		this.scrollToSelected();
	}
	updateSelection(count) {
		if (!this.list) return;
		this.list.querySelectorAll(".cp-item").forEach((el, i) => {
			el.classList.toggle("cp-item--selected", i === this.selectedIdx);
		});
	}
	scrollToSelected() {
		if (!this.list) return;
		this.list.querySelector(".cp-item--selected")?.scrollIntoView({ block: "nearest" });
	}
	executeSelected(filtered) {
		const def = (filtered ?? this.filter(this.input?.value ?? ""))[this.selectedIdx];
		if (!def) return;
		this.close();
		this.dispatcher.dispatch(def.id);
	}
};
